create or replace function public.poker_registration_freeze(p_tournament uuid,p_expected integer) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare t public.poker_tournaments%rowtype; f poker_private.registration_finalizations%rowtype; ids uuid[];
begin
 if p_expected is null or p_expected not between 2 and 6 then raise exception 'Invalid expected roster'; end if;
 select * into t from public.poker_tournaments where id=p_tournament for update;
 if not found then raise exception 'Tournament unavailable'; end if;
 select * into f from poker_private.registration_finalizations where tournament_id=p_tournament;
 if not found then
  if not t.published or clock_timestamp()>=t.starts_at or not exists(select 1 from poker_private.registration_policies where tournament_id=t.id)
    or exists(select 1 from poker_private.tournament_rooms where tournament_id=t.id) then raise exception 'Finalization unavailable'; end if;
  select array_agg(member_id order by created_at,member_id) into ids from poker_private.tournament_registrations where tournament_id=t.id;
  if coalesce(cardinality(ids),0)<>p_expected then raise exception 'Require 2-6 registered players'; end if;
  insert into poker_private.registration_finalizations(tournament_id,room_id,starts_at,structure,members,capacity)
   values(t.id,gen_random_uuid(),t.starts_at,t.structure,ids,case when cardinality(ids)=2 then 2 else 6 end) returning * into f;
  update poker_private.registration_policies set enabled=false where tournament_id=t.id;
 end if;
 if cardinality(f.members)<>p_expected then raise exception 'Roster count changed'; end if;
 return jsonb_build_object('tournamentId',f.tournament_id,'roomId',f.room_id,'starts_at',f.starts_at,'structure',f.structure,'members',f.members,'capacity',f.capacity,'allowSpectators',false);
end;
$$;
revoke all on function public.poker_registration_management_status(uuid),public.poker_registration_freeze(uuid,integer) from public,anon,authenticated;
grant execute on function public.poker_registration_management_status(uuid),public.poker_registration_freeze(uuid,integer) to service_role;

-- Freeze blocks intake/config changes before encrypted checkpoint provisioning begins.
create or replace function public.poker_registration_status(p_tournament uuid,p_member uuid) returns jsonb
language sql volatile security invoker set search_path='' as $$
 select jsonb_build_object('tournamentId',t.id,'title',t.title,'starts_at',t.starts_at,'capacity',p.capacity,
  'count',(select count(*) from poker_private.tournament_registrations e where e.tournament_id=t.id),
  'registered',exists(select 1 from poker_private.tournament_registrations e where e.tournament_id=t.id and e.member_id=p_member),
  'assigned',exists(select 1 from poker_private.room_admissions a where a.tournament_id=t.id and a.member_id=p_member),
  'registrationOpen',p.enabled and t.published and clock_timestamp()<t.starts_at and not exists(select 1 from poker_private.tournament_rooms r where r.tournament_id=t.id) and not exists(select 1 from poker_private.registration_finalizations f where f.tournament_id=t.id),
  'canCancel',clock_timestamp()<t.starts_at and not exists(select 1 from poker_private.tournament_rooms r where r.tournament_id=t.id) and not exists(select 1 from poker_private.registration_finalizations f where f.tournament_id=t.id)
    and exists(select 1 from poker_private.tournament_registrations e where e.tournament_id=t.id and e.member_id=p_member))
 from public.poker_tournaments t join poker_private.registration_policies p on p.tournament_id=t.id where t.id=p_tournament;
$$;
create or replace function public.poker_registration_configure(p_tournament uuid,p_capacity integer,p_enabled boolean) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare t public.poker_tournaments%rowtype; n integer;
begin
 if p_capacity is null or p_capacity not between 2 and 600 or p_enabled is null then raise exception 'Invalid registration policy'; end if;
 select * into t from public.poker_tournaments where id=p_tournament for update;
 if not found or clock_timestamp()>=t.starts_at or exists(select 1 from poker_private.tournament_rooms where tournament_id=p_tournament) or exists(select 1 from poker_private.registration_finalizations where tournament_id=p_tournament) then raise exception 'Registration policy locked'; end if;
 select count(*) into n from poker_private.tournament_registrations where tournament_id=p_tournament;
 if n>p_capacity then raise exception 'Capacity below registrations'; end if;
 insert into poker_private.registration_policies values(p_tournament,p_capacity,p_enabled)
 on conflict(tournament_id) do update set capacity=excluded.capacity,enabled=excluded.enabled;
 return public.poker_registration_status(p_tournament,null);
end;
$$;
create or replace function public.poker_registration_change(p_tournament uuid,p_member uuid,p_action text) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare t public.poker_tournaments%rowtype; p poker_private.registration_policies%rowtype; present boolean; n integer;
begin
 if p_member is null or p_action is null or p_action not in ('register','cancel') then raise exception 'Invalid registration'; end if;
 -- All configure/register/cancel/provision paths lock the SAME tournament row first.
 select * into t from public.poker_tournaments where id=p_tournament for update;
 if not found then return jsonb_build_object('ok',false,'code','unavailable'); end if;
 select * into p from poker_private.registration_policies where tournament_id=p_tournament;
 if not found then return jsonb_build_object('ok',false,'code','unavailable'); end if;
 select exists(select 1 from poker_private.tournament_registrations where tournament_id=p_tournament and member_id=p_member) into present;
 if not t.published and not present then return jsonb_build_object('ok',false,'code','unavailable'); end if;
 if (p_action='register' and present) or (p_action='cancel' and not present) then
   return jsonb_build_object('ok',true,'state',public.poker_registration_status(p_tournament,p_member)); end if;
 -- Sample AFTER waiting for the row lock: transaction-start now() could admit late users.
 if clock_timestamp()>=t.starts_at or exists(select 1 from poker_private.tournament_rooms where tournament_id=p_tournament) or exists(select 1 from poker_private.registration_finalizations where tournament_id=p_tournament)
   or (p_action='register' and (not p.enabled or not t.published)) then return jsonb_build_object('ok',false,'code','closed'); end if;
 if p_action='register' then
   select count(*) into n from poker_private.tournament_registrations where tournament_id=p_tournament;
   if n>=p.capacity then return jsonb_build_object('ok',false,'code','full'); end if;
   insert into poker_private.tournament_registrations(tournament_id,member_id) values(p_tournament,p_member);
 else delete from poker_private.tournament_registrations where tournament_id=p_tournament and member_id=p_member; end if;
 return jsonb_build_object('ok',true,'state',public.poker_registration_status(p_tournament,p_member));
end;
$$;

-- Legacy rooms without intake retain their original trusted provision path.
create or replace function public.poker_room_provision(p_room uuid,p_tournament uuid,p_members uuid[],p_capacity integer,
 p_spectators boolean,p_starts timestamptz,p_structure jsonb) returns boolean
language plpgsql security invoker set search_path='' as $$
declare t public.poker_tournaments%rowtype; r poker_private.tournament_rooms%rowtype; v bigint; existing uuid[]; requested uuid[]; f poker_private.registration_finalizations%rowtype;
begin
 if p_room is null or p_tournament is null or p_capacity is null or p_capacity not in (2,6) or p_spectators is null
    or p_starts is null or p_structure is null or p_members is null or array_ndims(p_members) is distinct from 1
    or cardinality(p_members)<2 or cardinality(p_members)>p_capacity or array_position(p_members,null) is not null
    or (select count(distinct m) from unnest(p_members) m)<>cardinality(p_members) then raise exception 'Invalid room admission'; end if;
 select array_agg(m order by m) into requested from unnest(p_members) m;
 -- Lock tournament first for all provisions: avoids duplicate/moved participant races.
 select * into t from public.poker_tournaments where id=p_tournament for update;
 if not found then raise exception 'Tournament unavailable'; end if;
 select * into f from poker_private.registration_finalizations where tournament_id=p_tournament;
 if exists(select 1 from poker_private.registration_policies where tournament_id=p_tournament) then
  if f.tournament_id is null or f.room_id<>p_room or f.capacity<>p_capacity or p_spectators or f.starts_at<>p_starts or f.structure<>p_structure
    or requested<>(select array_agg(m order by m) from unnest(f.members) m) then raise exception 'Frozen registration roster required'; end if;
 end if;
 select * into r from poker_private.tournament_rooms where room_id=p_room;
 if found then
   select array_agg(member_id order by member_id) into existing from poker_private.room_admissions where room_id=p_room;
   if r.tournament_id=p_tournament and r.capacity=p_capacity and r.allow_spectators=p_spectators
      and r.starts_at=p_starts and r.structure=p_structure and existing=requested then return true; end if;
   raise exception 'Room already provisioned';
 end if;
 if not t.published or t.starts_at<=clock_timestamp() or t.starts_at<>p_starts or t.structure<>p_structure then raise exception 'Tournament changed or registration closed'; end if;
 -- Only the pristine committed empty-room checkpoint can receive its immutable roster.
 select version into v from poker_private.room_checkpoints where room_id=p_room for update;
 if not found or v<>1 then raise exception 'Room is not pristine'; end if;
 if clock_timestamp()>=t.starts_at then raise exception 'Registration closed while awaiting checkpoint'; end if;
 insert into poker_private.tournament_rooms(room_id,tournament_id,starts_at,structure,capacity,allow_spectators,expected_count)
   values(p_room,p_tournament,p_starts,p_structure,p_capacity,p_spectators,cardinality(p_members));
 insert into poker_private.room_admissions(tournament_id,room_id,member_id)
   select p_tournament,p_room,m from unnest(p_members) m;
 return true;
end;
$$;

-- 20261017065003_poker_room_startup_discovery.sql
-- Prepared only: trusted startup discovery. No browser execution or plaintext state.
create index if not exists tournament_rooms_enabled_startup on poker_private.tournament_rooms(room_id) where enabled;

create or replace function public.poker_room_startup_ids(p_limit integer) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare result jsonb;
begin
 if p_limit is null or p_limit<1 or p_limit>10000 then raise exception 'Invalid startup limit'; end if;
 -- Read one extra ID so the owner cannot silently omit rooms at its capacity.
 -- Include unpublished/finished rooms: ongoing continuity and saved results
 -- must not depend on current publication or an untrusted plaintext shortcut.
 select coalesce(jsonb_agg(room_id order by room_id),'[]'::jsonb) into result
 from (select room_id from poker_private.tournament_rooms where enabled
       order by room_id limit p_limit+1) rooms;
 return result;
end;
$$;
revoke all on function public.poker_room_startup_ids(integer) from public,anon,authenticated;
grant execute on function public.poker_room_startup_ids(integer) to service_role;

-- 20261018174354_poker_statistics.sql
-- Result archive is independent of live room lifetime. No client may submit results.
create table if not exists poker_private.tournament_finishes(
 tournament_id uuid primary key references public.poker_tournaments(id) on delete restrict,
 room_id uuid not null unique references poker_private.tournament_rooms(room_id),
 hand_id uuid not null,
 finished_at timestamptz not null,
 standings jsonb not null check(jsonb_typeof(standings)='array')
);
create table if not exists poker_private.ring_accounts(
 member_id uuid primary key references auth.users(id) on delete restrict,
 available bigint not null default 0 check(available between 0 and 4503599627370495),
 in_play bigint not null default 0 check(in_play between 0 and 4503599627370495),
 updated_at timestamptz not null default now()
);
alter table poker_private.tournament_finishes enable row level security;
alter table poker_private.ring_accounts enable row level security;
revoke all on poker_private.tournament_finishes,poker_private.ring_accounts from public,anon,authenticated;
grant select,insert on poker_private.tournament_finishes to service_role;
-- Read model only; ring-game ledger integration will own balance mutations.
grant select on poker_private.ring_accounts to service_role;
create or replace function poker_private.archive_tournament_finish() returns trigger
language plpgsql security definer set search_path='' as $$
declare tid uuid; rows jsonb; existing jsonb; expected integer;
begin
 if nullif(new.result#>>'{tournament,champion}','') is null then return new; end if;
 select tournament_id into tid from poker_private.tournament_rooms where room_id=new.room_id;
 if tid is null then return new; end if;
 -- Legacy records do not carry the authoritative seat/member mapping. Never guess it.
 if jsonb_typeof(new.result->'participants') is distinct from 'array' then return new; end if;
 select count(*) into expected from poker_private.room_admissions where room_id=new.room_id;
 if expected<2 or jsonb_array_length(new.result->'participants')<>expected then raise exception 'Invalid result roster'; end if;
 select jsonb_agg(jsonb_build_object('memberId',p->>'memberId','seatId',p->>'seatId',
   'name',coalesce(nullif(u.raw_user_meta_data->>'display_name',''),'会員'),
   'place',case when p->>'seatId'=new.result#>>'{tournament,champion}' then 1 else (e->>'place')::integer end,
   'tiedThrough',case when p->>'seatId'=new.result#>>'{tournament,champion}' then 1 else (e->>'tiedThrough')::integer end)
   order by case when p->>'seatId'=new.result#>>'{tournament,champion}' then 1 else (e->>'place')::integer end,p->>'seatId') into rows
 from jsonb_array_elements(new.result->'participants') p
 join poker_private.room_admissions a on a.room_id=new.room_id and a.member_id=(p->>'memberId')::uuid
 join auth.users u on u.id=a.member_id
 left join lateral (select x as e from jsonb_array_elements(new.result#>'{tournament,eliminated}') x where x->>'id'=p->>'seatId') elim on true;
 if rows is null or jsonb_array_length(rows)<>expected
 or (select count(distinct x->>'memberId') from jsonb_array_elements(rows) x)<>expected
 or (select count(distinct x->>'seatId') from jsonb_array_elements(rows) x)<>expected
 or (select count(*) from jsonb_array_elements(rows) x where (x->>'place')::integer=1)<>1
 or exists(select 1 from jsonb_array_elements(rows) x where x->>'place' is null or x->>'tiedThrough' is null or (x->>'place')::integer<1 or (x->>'tiedThrough')::integer<(x->>'place')::integer or (x->>'tiedThrough')::integer>expected)
 then raise exception 'Invalid final standings'; end if;
 insert into poker_private.tournament_finishes values(tid,new.room_id,new.hand_id,new.created_at,rows) on conflict(tournament_id) do nothing;
 select standings into existing from poker_private.tournament_finishes where tournament_id=tid;
 if existing is distinct from rows then raise exception 'Conflicting tournament outcome'; end if;
 return new;
end;
$$;
revoke all on function poker_private.archive_tournament_finish() from public,anon,authenticated; do $release$ begin create trigger archive_tournament_finish after insert or update of result on poker_private.hand_results for each row execute function poker_private.archive_tournament_finish(); exception when duplicate_object or duplicate_table or duplicate_function or undefined_function then null; end $release$;;

-- Session-scoped read API: caller identity is never accepted as a parameter.
create or replace function public.poker_statistics(p_admin boolean default false) returns jsonb
language plpgsql security definer set search_path='' as $$
declare who uuid:=auth.uid(); payload jsonb;
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required'; end if;
 if p_admin and not coalesce(public.is_admin(),false) then raise exception 'Admin required'; end if;
 with finishes as (
 select f.tournament_id,t.title,f.finished_at,x as row
 from poker_private.tournament_finishes f join public.poker_tournaments t on t.id=f.tournament_id cross join lateral jsonb_array_elements(f.standings) x
 ), totals as (
 select row->>'memberId' member_id,max(row->>'name') name,count(*) played,
 count(*) filter(where (row->>'place')::integer=1) firsts,
 count(*) filter(where (row->>'place')::integer=2) seconds,
 count(*) filter(where (row->>'place')::integer=3) thirds from finishes group by row->>'memberId'
 ), rings as (
 select member_id,available,in_play,available+in_play total,updated_at,rank() over(order by available+in_play desc) position from poker_private.ring_accounts
 )
 select jsonb_build_object('asOf',now(),
 'players',coalesce((select jsonb_agg(to_jsonb(q)) from (select * from totals where p_admin or member_id=who::text order by firsts desc,seconds desc,thirds desc,member_id limit 500) q),'[]'::jsonb),
 'history',coalesce((select jsonb_agg(to_jsonb(q)) from (select tournament_id,title,finished_at,row from finishes where p_admin or row->>'memberId'=who::text order by finished_at desc,tournament_id limit 500) q),'[]'::jsonb),
 'ring',coalesce((select jsonb_agg(to_jsonb(q)) from (select r.*,coalesce(nullif(u.raw_user_meta_data->>'display_name',''),'会員') name from rings r join auth.users u on u.id=r.member_id where p_admin or r.member_id=who order by position,r.member_id limit 500) q),'[]'::jsonb),
 'upcoming',coalesce((select jsonb_agg(to_jsonb(q)) from (select t.id,t.title,t.starts_at,a.room_id from poker_private.tournament_registrations reg join public.poker_tournaments t on t.id=reg.tournament_id left join poker_private.room_admissions a on a.tournament_id=t.id and a.member_id=reg.member_id where reg.member_id=who and not exists(select 1 from poker_private.tournament_finishes f where f.tournament_id=t.id) order by t.starts_at limit 100) q),'[]'::jsonb)) into payload;
 return payload;
end;
$$;
revoke all on function public.poker_statistics(boolean) from public,anon;
grant execute on function public.poker_statistics(boolean) to authenticated;

-- Allow atomic enrichment only through the existing server-owned save path.
grant update on poker_private.hand_results to service_role;
create or replace function public.poker_room_save(p_room uuid,p_expected bigint,p_write uuid,p_sealed jsonb,p_result jsonb)
returns bigint language plpgsql security invoker set search_path = '' as $$
declare current_row poker_private.room_checkpoints%rowtype; existing_result jsonb; h uuid;
begin
 if p_room is null or p_write is null or p_expected is null or p_expected<0 or p_expected>=9007199254740991
    or p_sealed is null or jsonb_typeof(p_sealed)<>'object'
    or (p_sealed->>'format') is distinct from '1'
    or coalesce(length(p_sealed->>'data'),0)<1 or length(p_sealed::text)>3000000
    or coalesce(length(p_sealed->>'iv'),0)<>16 or coalesce(length(p_sealed->>'tag'),0)<>24
    or coalesce(p_sealed->>'keyId','') !~ '^[a-zA-Z0-9_-]{1,80}$' then
   raise exception 'Invalid checkpoint';
 end if;
 if p_result is not null and (jsonb_typeof(p_result)<>'object' or p_result->>'handId' is null
    or jsonb_typeof(p_result->'payouts') is distinct from 'object'
    or jsonb_typeof(p_result->'winners') is distinct from 'array' or length(p_result::text)>10000) then
   raise exception 'Invalid terminal result';
 end if;
 -- The insert and row lock serialize initial creation as well as existing owners.
 if p_expected=0 then
   insert into poker_private.room_checkpoints(room_id,version,write_id,sealed)
     values(p_room,0,p_write,p_sealed) on conflict(room_id) do nothing;
 end if;
 select * into current_row from poker_private.room_checkpoints where room_id=p_room for update;
 if not found then raise exception 'Checkpoint conflict'; end if;
 if current_row.version=p_expected+1 and current_row.write_id=p_write
    and current_row.sealed=p_sealed and current_row.last_result is not distinct from p_result then
   return current_row.version; -- lost response retry: no duplicate log or award
 end if;
 if current_row.version<>p_expected or (current_row.version>0 and current_row.write_id=p_write) then
   raise exception 'Checkpoint conflict';
 end if;
 if p_result is not null then
   h=(p_result->>'handId')::uuid;
   insert into poker_private.hand_results(room_id,hand_id,result) values(p_room,h,p_result)
     on conflict(room_id,hand_id) do nothing;
   select result into existing_result from poker_private.hand_results where room_id=p_room and hand_id=h;
   if existing_result is distinct from p_result then
     -- One-way enrichment of legacy records with server-owned seat/member mapping.
     if not (existing_result ? 'participants') and p_result ? 'participants'
        and existing_result = p_result - 'participants' then
       update poker_private.hand_results set result=p_result where room_id=p_room and hand_id=h;
     else raise exception 'Terminal result conflict'; end if;
   end if;
 end if;
 update poker_private.room_checkpoints set version=p_expected+1,write_id=p_write,sealed=p_sealed,
   last_result=p_result,updated_at=now() where room_id=p_room;
 return p_expected+1;
end;
$$;

