-- 20261026120000_poker_hand_histories.sql
-- Hand histories (2026/10/26): one readable record per settled ring/tournament hand.
-- The record holds EVERY player's hole cards. Operators may see them all (fraud checks);
-- members see only their own cards and cards shown at showdown, through the read RPCs below.
create table if not exists poker_private.hand_histories(
 hand_id uuid primary key,
 kind text not null check(kind in('ring','tournament')),
 source_id uuid not null,
 hand_number integer check(hand_number is null or hand_number>=0),
 played_at timestamptz not null default now(),
 record jsonb not null check(jsonb_typeof(record)='object' and length(record::text)<=200000)
);
create table if not exists poker_private.hand_history_members(
 hand_id uuid not null references poker_private.hand_histories(hand_id),
 member_id uuid not null,
 seat_id text not null check(seat_id ~ '^seat-[1-6]$'),
 net bigint not null,
 played_at timestamptz not null,
 primary key(hand_id,member_id)
);
create index if not exists hand_history_members_member_played on poker_private.hand_history_members(member_id,played_at desc);
create index if not exists hand_histories_played on poker_private.hand_histories(played_at desc);
alter table poker_private.hand_histories enable row level security;
alter table poker_private.hand_history_members enable row level security;
revoke all on poker_private.hand_histories,poker_private.hand_history_members from public,anon,authenticated;
grant select,insert on poker_private.hand_histories,poker_private.hand_history_members to service_role;

-- Server-owned write path only (game server, service role). Idempotent per hand.
create or replace function public.poker_hand_history_save(p_hand uuid,p_kind text,p_source uuid,p_hand_number integer,p_record jsonb)
returns boolean language plpgsql security invoker set search_path='' as $$
declare inserted uuid;
begin
 if p_hand is null or p_source is null or p_kind is null or p_kind not in('ring','tournament')
    or p_record is null or jsonb_typeof(p_record)<>'object' or length(p_record::text)>200000
    or p_record->>'version' is distinct from '1' or p_record->>'handId' is distinct from p_hand::text
    or jsonb_typeof(p_record->'players') is distinct from 'array'
    or jsonb_array_length(p_record->'players') not between 2 and 6
    or jsonb_typeof(p_record->'actions') is distinct from 'array'
    or exists(select 1 from jsonb_array_elements(p_record->'players') p
      where coalesce(p->>'seatId','') !~ '^seat-[1-6]$'
         or coalesce(p->>'memberId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or jsonb_typeof(p->'net') is distinct from 'number'
         or jsonb_typeof(p->'hole') is distinct from 'array')
    or (select count(distinct p->>'memberId') from jsonb_array_elements(p_record->'players') p)<>jsonb_array_length(p_record->'players')
    or (select count(distinct p->>'seatId') from jsonb_array_elements(p_record->'players') p)<>jsonb_array_length(p_record->'players') then
   raise exception 'Invalid hand history';
 end if;
 insert into poker_private.hand_histories(hand_id,kind,source_id,hand_number,record)
   values(p_hand,p_kind,p_source,p_hand_number,p_record) on conflict(hand_id) do nothing returning hand_id into inserted;
 if inserted is null then return false; end if;
 insert into poker_private.hand_history_members(hand_id,member_id,seat_id,net,played_at)
   select p_hand,(p->>'memberId')::uuid,p->>'seatId',(p->>'net')::bigint,h.played_at
   from jsonb_array_elements(p_record->'players') p cross join poker_private.hand_histories h where h.hand_id=p_hand;
 return true;
end;
$$;
revoke all on function public.poker_hand_history_save(uuid,text,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.poker_hand_history_save(uuid,text,uuid,integer,jsonb) to service_role;

-- Display title for a hand: ring table title or tournament title.
create or replace function poker_private.hand_history_title(p_kind text,p_source uuid) returns text
language sql stable security definer set search_path='' as $$
 select case when p_kind='ring' then (select t.title from public.poker_ring_tables t where t.id=p_source)
  else (select t.title from poker_private.tournament_rooms r join public.poker_tournaments t on t.id=r.tournament_id where r.room_id=p_source) end;
$$;
revoke all on function poker_private.hand_history_title(text,uuid) from public,anon,authenticated;

-- Member-safe projection. Caller identity is never a parameter.
create or replace function poker_private.hand_history_view(h poker_private.hand_histories,who uuid,p_admin boolean) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'handId',h.hand_id,'kind',h.kind,'title',poker_private.hand_history_title(h.kind,h.source_id),
  'handNumber',h.hand_number,'playedAt',h.played_at,'terms',h.record->'terms','buttonSeatId',h.record->'buttonSeatId',
  'board',h.record->'board','actions',h.record->'actions','result',h.record->'result',
  'players',(select jsonb_agg(
     jsonb_build_object('seatId',p->>'seatId','seat',(p->>'seat')::integer,'position',p->>'position',
      'name',coalesce(nullif(u.raw_user_meta_data->>'display_name',''),'会員'),
      'startStack',p->'startStack','endStack',p->'endStack','net',p->'net','folded',p->'folded','shown',p->'shown',
      'you',(p->>'memberId')=who::text,
      'hole',case when p_admin or (p->>'memberId')=who::text or (p->>'shown')::boolean then p->'hole' else null end)
     ||case when p_admin then jsonb_build_object('memberId',p->>'memberId') else '{}'::jsonb end
     order by (p->>'seat')::integer)
   from jsonb_array_elements(h.record->'players') p left join auth.users u on u.id::text=p->>'memberId'));
$$;
revoke all on function poker_private.hand_history_view(poker_private.hand_histories,uuid,boolean) from public,anon,authenticated;

create or replace function public.poker_hand_history_list(p_admin boolean default false,p_before timestamptz default null,p_limit integer default 20)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare who uuid:=auth.uid(); lim integer:=least(greatest(coalesce(p_limit,20),1),100);
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required'; end if;
 if p_admin and not coalesce(public.is_admin(),false) then raise exception 'Admin required'; end if;
 return coalesce((select jsonb_agg(poker_private.hand_history_view(h,who,p_admin) order by h.played_at desc,h.hand_id)
  from (select h.* from poker_private.hand_histories h
        where (p_admin or exists(select 1 from poker_private.hand_history_members m where m.hand_id=h.hand_id and m.member_id=who))
          and (p_before is null or h.played_at<p_before)
        order by h.played_at desc,h.hand_id limit lim) h),'[]'::jsonb);
end;
$$;
revoke all on function public.poker_hand_history_list(boolean,timestamptz,integer) from public,anon;
grant execute on function public.poker_hand_history_list(boolean,timestamptz,integer) to authenticated;

create or replace function public.poker_hand_history_detail(p_hand uuid,p_admin boolean default false)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare who uuid:=auth.uid(); h poker_private.hand_histories;
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required'; end if;
 if p_admin and not coalesce(public.is_admin(),false) then raise exception 'Admin required'; end if;
 select * into h from poker_private.hand_histories where hand_id=p_hand;
 if not found or not (p_admin or exists(select 1 from poker_private.hand_history_members m where m.hand_id=p_hand and m.member_id=who)) then return null; end if;
 return poker_private.hand_history_view(h,who,p_admin);
end;
$$;
revoke all on function public.poker_hand_history_detail(uuid,boolean) from public,anon;
grant execute on function public.poker_hand_history_detail(uuid,boolean) to authenticated;

-- 20261026130000_poker_hand_stats.sql
-- Tendency statistics (2026/10/26): per-player flags computed at save time (lib/poker/hand-stats.ts)
-- are kept next to each member's hand row, so totals stay cheap however many hands are played.
alter table poker_private.hand_history_members add column if not exists stats jsonb not null default '{}'::jsonb;
alter table poker_private.hand_history_members add column if not exists bb integer;
do $$ begin
 if not exists(select 1 from pg_constraint where conname='hand_history_members_stats_object') then
  alter table poker_private.hand_history_members add constraint hand_history_members_stats_object check(jsonb_typeof(stats)='object' and length(stats::text)<=2000);
 end if;
end $$;

create or replace function public.poker_hand_history_save(p_hand uuid,p_kind text,p_source uuid,p_hand_number integer,p_record jsonb)
returns boolean language plpgsql security invoker set search_path='' as $$
declare inserted uuid;
begin
 if p_hand is null or p_source is null or p_kind is null or p_kind not in('ring','tournament')
    or p_record is null or jsonb_typeof(p_record)<>'object' or length(p_record::text)>200000
    or p_record->>'version' is distinct from '1' or p_record->>'handId' is distinct from p_hand::text
    or jsonb_typeof(p_record->'players') is distinct from 'array'
    or jsonb_array_length(p_record->'players') not between 2 and 6
    or jsonb_typeof(p_record->'actions') is distinct from 'array'
    or jsonb_typeof(p_record#>'{terms,bb}') is distinct from 'number'
    or exists(select 1 from jsonb_array_elements(p_record->'players') p
      where coalesce(p->>'seatId','') !~ '^seat-[1-6]$'
         or coalesce(p->>'memberId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         or jsonb_typeof(p->'net') is distinct from 'number'
         or jsonb_typeof(p->'hole') is distinct from 'array'
         or (p ? 'stats' and jsonb_typeof(p->'stats') is distinct from 'object'))
    or (select count(distinct p->>'memberId') from jsonb_array_elements(p_record->'players') p)<>jsonb_array_length(p_record->'players')
    or (select count(distinct p->>'seatId') from jsonb_array_elements(p_record->'players') p)<>jsonb_array_length(p_record->'players') then
   raise exception 'Invalid hand history';
 end if;
 insert into poker_private.hand_histories(hand_id,kind,source_id,hand_number,record)
   values(p_hand,p_kind,p_source,p_hand_number,p_record) on conflict(hand_id) do nothing returning hand_id into inserted;
 if inserted is null then return false; end if;
 insert into poker_private.hand_history_members(hand_id,member_id,seat_id,net,played_at,stats,bb)
   select p_hand,(p->>'memberId')::uuid,p->>'seatId',(p->>'net')::bigint,h.played_at,
     coalesce(p->'stats','{}'::jsonb)||jsonb_build_object('position',p->>'position'),(p_record#>>'{terms,bb}')::integer
   from jsonb_array_elements(p_record->'players') p cross join poker_private.hand_histories h where h.hand_id=p_hand;
 return true;
end;
$$;
revoke all on function public.poker_hand_history_save(uuid,text,uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.poker_hand_history_save(uuid,text,uuid,integer,jsonb) to service_role;

-- Aggregate one member's rows. Counts are returned as numerator/denominator so the page can show sample size.
create or replace function poker_private.hand_stats_summary(p_member uuid,p_kind text) returns jsonb
language sql stable security definer set search_path='' as $$
 with rows as (
  select m.* from poker_private.hand_history_members m join poker_private.hand_histories h on h.hand_id=m.hand_id
  where m.member_id=p_member and (p_kind is null or h.kind=p_kind)
 ), f as (
  select count(*) hands,coalesce(sum(net),0) net,
   coalesce(sum(case when bb>0 then net::numeric/bb end),0) net_bb,
   count(*) filter(where (stats->>'vpip')::boolean) vpip,
   count(*) filter(where (stats->>'pfr')::boolean) pfr,
   count(*) filter(where (stats->>'threeBetOpp')::boolean) three_bet_opp,
   count(*) filter(where (stats->>'threeBet')::boolean) three_bet,
   count(*) filter(where (stats->>'foldTo3BetOpp')::boolean) fold_to_3bet_opp,
   count(*) filter(where (stats->>'foldTo3Bet')::boolean) fold_to_3bet,
   count(*) filter(where (stats->>'cbetOpp')::boolean) cbet_opp,
   count(*) filter(where (stats->>'cbet')::boolean) cbet,
   count(*) filter(where (stats->>'foldToCbetOpp')::boolean) fold_to_cbet_opp,
   count(*) filter(where (stats->>'foldToCbet')::boolean) fold_to_cbet,
   count(*) filter(where (stats->>'sawFlop')::boolean) saw_flop,
   count(*) filter(where (stats->>'wentToShowdown')::boolean) wtsd,
   count(*) filter(where (stats->>'wonAtShowdown')::boolean) wsd
  from rows
 )
 select to_jsonb(f)||jsonb_build_object(
  'bb100',case when f.hands>0 then round(f.net_bb*100/f.hands,2) else 0 end,
  'positions',coalesce((select jsonb_agg(jsonb_build_object('position',position,'hands',hands,'net',net,
     'bb100',case when hands>0 then round(net_bb*100/hands,2) else 0 end,'vpip',vpip,'pfr',pfr) order by array_position(array['UTG','HJ','CO','BTN','SB','BB'],position))
   from (select stats->>'position' position,count(*) hands,sum(net) net,sum(case when bb>0 then net::numeric/bb end) net_bb,
     count(*) filter(where (stats->>'vpip')::boolean) vpip,count(*) filter(where (stats->>'pfr')::boolean) pfr
     from rows where stats ? 'position' group by stats->>'position') q),'[]'::jsonb))
 from f;
$$;
revoke all on function poker_private.hand_stats_summary(uuid,text) from public,anon,authenticated;

-- Session-scoped read API. Members get their own totals; operators get every member's headline numbers.
create or replace function public.poker_hand_stats(p_admin boolean default false)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare who uuid:=auth.uid();
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required'; end if;
 if not p_admin then
  return jsonb_build_object('asOf',now(),'ring',poker_private.hand_stats_summary(who,'ring'),'all',poker_private.hand_stats_summary(who,null));
 end if;
 if not coalesce(public.is_admin(),false) then raise exception 'Admin required'; end if;
 return jsonb_build_object('asOf',now(),'members',coalesce((select jsonb_agg(x order by (x->>'hands')::integer desc) from (
   select jsonb_build_object('memberId',m.member_id,'name',coalesce(nullif(u.raw_user_meta_data->>'display_name',''),'会員'))||poker_private.hand_stats_summary(m.member_id,'ring') x
   from (select distinct member_id from poker_private.hand_history_members) m left join auth.users u on u.id=m.member_id limit 500) q),'[]'::jsonb));
end;
$$;
revoke all on function public.poker_hand_stats(boolean) from public,anon;
grant execute on function public.poker_hand_stats(boolean) to authenticated;

-- 20261027010000_poker_shop_tickets.sql
-- Summit chip exchange: members trade available ring chips for tickets (time bank, rabbit).
-- Prices are set by admins later; an item without a price is not offered. Tickets are used in ring games only.
create table if not exists poker_private.shop_items(
 code text primary key check(code ~ '^[a-z_]{1,32}$'),
 label text not null check(length(label) between 1 and 40),
 description text not null default '' check(length(description)<=200),
 price bigint check(price is null or (price>=1 and price<=1000000)),
 active boolean not null default true,
 sort integer not null default 0,
 updated_at timestamptz not null default now()
);
alter table poker_private.shop_items enable row level security;
insert into poker_private.shop_items(code,label,description,sort) values
 ('time_bank','タイムバンク +30秒','リングで持ち時間を30秒延ばせます。',1),
 ('rabbit','ラビット','リングで途中で終わったハンドの、残りのボードを見られます。',2)
on conflict (code) do nothing;

create table if not exists poker_private.member_tickets(
 member_id uuid not null references auth.users(id) on delete cascade,
 item text not null references poker_private.shop_items(code),
 count integer not null default 0 check(count>=0 and count<=100000),
 updated_at timestamptz not null default now(),
 primary key(member_id,item)
);
alter table poker_private.member_tickets enable row level security;

create table if not exists poker_private.shop_ledger(
 id bigint generated always as identity primary key,
 member_id uuid not null references poker_private.ring_accounts(member_id),
 request_id uuid not null,
 item text not null references poker_private.shop_items(code),
 quantity integer not null check(quantity between 1 and 10),
 price_each bigint not null check(price_each>=1),
 total bigint not null check(total=price_each*quantity),
 created_at timestamptz not null default now(),
 unique(member_id,request_id)
);
alter table poker_private.shop_ledger enable row level security;

create table if not exists poker_private.ticket_uses(
 id bigint generated always as identity primary key,
 member_id uuid not null references auth.users(id) on delete cascade,
 item text not null references poker_private.shop_items(code),
 ref text not null check(length(ref) between 1 and 200),
 created_at timestamptz not null default now(),
 unique(member_id,item,ref)
);
alter table poker_private.ticket_uses enable row level security;

-- What the signed-in member sees in the exchange: priced items, their ticket counts and spendable chips.
create or replace function poker_private.shop_view() returns jsonb language plpgsql security definer set search_path='' as $$
declare who uuid:=auth.uid();
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required';end if;
 perform poker_private.ensure_ring_welcome(who);
 return jsonb_build_object(
  'available',coalesce((select available from poker_private.ring_accounts where member_id=who),0),
  'items',coalesce((select jsonb_agg(jsonb_build_object('code',i.code,'label',i.label,'description',i.description,'price',i.price) order by i.sort,i.code) from poker_private.shop_items i where i.active and i.price is not null),'[]'::jsonb),
  'tickets',coalesce((select jsonb_object_agg(t.item,t.count) from poker_private.member_tickets t where t.member_id=who and t.count>0),'{}'::jsonb),
  'history',coalesce((select jsonb_agg(to_jsonb(h)) from(select l.item,i.label,l.quantity,l.total,l.created_at as "createdAt" from poker_private.shop_ledger l join poker_private.shop_items i on i.code=l.item where l.member_id=who order by l.created_at desc,l.id desc limit 10) h),'[]'::jsonb));
end;$$;
revoke all on function poker_private.shop_view() from public,anon,service_role;
grant execute on function poker_private.shop_view() to authenticated;
create or replace function public.poker_shop() returns jsonb language sql security invoker set search_path='' as $$select poker_private.shop_view();$$;
revoke all on function public.poker_shop() from public,anon,service_role;
grant execute on function public.poker_shop() to authenticated;

-- Exchange chips for tickets. A repeated request id returns the first result without charging again.
create or replace function poker_private.shop_exchange(p_item text,p_quantity integer,p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare who uuid:=auth.uid();i poker_private.shop_items%rowtype;a poker_private.ring_accounts%rowtype;prior poker_private.shop_ledger%rowtype;cost bigint;
begin
 if who is null or coalesce(public.is_suspended(),true) then raise exception 'Login required';end if;
 if p_request is null or p_quantity is null or p_quantity<1 or p_quantity>10 then raise exception 'Invalid exchange';end if;
 perform poker_private.ensure_ring_welcome(who);
 select * into a from poker_private.ring_accounts where member_id=who for update;
 if not found then raise exception 'Account unavailable';end if;
 select * into prior from poker_private.shop_ledger where member_id=who and request_id=p_request;
 if found then
  if prior.item<>p_item or prior.quantity<>p_quantity then raise exception 'Request conflict';end if;
  return poker_private.shop_view();
 end if;
 select * into i from poker_private.shop_items where code=p_item;
 if not found or not i.active or i.price is null then raise exception 'Item unavailable';end if;
 cost:=i.price*p_quantity;
 if a.available<cost then raise exception 'Insufficient chips';end if;
 update poker_private.ring_accounts set available=available-cost,updated_at=now() where member_id=who;
 insert into poker_private.shop_ledger(member_id,request_id,item,quantity,price_each,total) values(who,p_request,p_item,p_quantity,i.price,cost);
 insert into poker_private.member_tickets(member_id,item,count) values(who,p_item,p_quantity)
  on conflict (member_id,item) do update set count=poker_private.member_tickets.count+excluded.count,updated_at=now();
 return poker_private.shop_view();
end;$$;
revoke all on function poker_private.shop_exchange(text,integer,uuid) from public,anon,service_role;
grant execute on function poker_private.shop_exchange(text,integer,uuid) to authenticated;
create or replace function public.poker_shop_exchange(p_item text,p_quantity integer,p_request uuid) returns jsonb language sql security invoker set search_path='' as $$select poker_private.shop_exchange(p_item,p_quantity,p_request);$$;
revoke all on function public.poker_shop_exchange(text,integer,uuid) from public,anon,service_role;
grant execute on function public.poker_shop_exchange(text,integer,uuid) to authenticated;

-- Server-only: spend one ticket for a game action. The same ref never spends twice.
create or replace function poker_private.ticket_use(p_member uuid,p_item text,p_ref text) returns boolean language plpgsql security definer set search_path='' as $$
declare left_count integer;
begin
 if p_member is null or p_item is null or p_ref is null or length(p_ref) not between 1 and 200 then raise exception 'Invalid ticket use';end if;
 if exists(select 1 from poker_private.ticket_uses where member_id=p_member and item=p_item and ref=p_ref) then return true;end if;
 update poker_private.member_tickets set count=count-1,updated_at=now() where member_id=p_member and item=p_item and count>0 returning count into left_count;
 if not found then return false;end if;
 insert into poker_private.ticket_uses(member_id,item,ref) values(p_member,p_item,p_ref);
 return true;
end;$$;
revoke all on function poker_private.ticket_use(uuid,text,text) from public,anon,authenticated,service_role;
create or replace function public.poker_ticket_use(p_member uuid,p_item text,p_ref text) returns boolean language sql security invoker set search_path='' as $$select poker_private.ticket_use(p_member,p_item,p_ref);$$;
revoke all on function public.poker_ticket_use(uuid,text,text) from public,anon,authenticated;
grant execute on function poker_private.ticket_use(uuid,text,text) to service_role;
grant execute on function public.poker_ticket_use(uuid,text,text) to service_role;

-- Admin: list every item (priced or not) and set price / on-off.
create or replace function poker_private.shop_admin_items() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not coalesce(public.is_admin(),false) or coalesce(public.is_suspended(),true) then raise exception 'Admin required';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('code',code,'label',label,'description',description,'price',price,'active',active) order by sort,code) from poker_private.shop_items),'[]'::jsonb);
end;$$;
revoke all on function poker_private.shop_admin_items() from public,anon,service_role;
grant execute on function poker_private.shop_admin_items() to authenticated;
create or replace function public.poker_admin_shop_items() returns jsonb language sql security invoker set search_path='' as $$select poker_private.shop_admin_items();$$;
revoke all on function public.poker_admin_shop_items() from public,anon,service_role;
grant execute on function public.poker_admin_shop_items() to authenticated;

create or replace function poker_private.shop_admin_save(p_item text,p_price bigint,p_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not coalesce(public.is_admin(),false) or coalesce(public.is_suspended(),true) then raise exception 'Admin required';end if;
 if p_active is null or (p_price is not null and (p_price<1 or p_price>1000000)) then raise exception 'Invalid price';end if;
 update poker_private.shop_items set price=p_price,active=p_active,updated_at=now() where code=p_item;
 if not found then raise exception 'Item unavailable';end if;
 return poker_private.shop_admin_items();
end;$$;
