-- 20261027020000_poker_ring_ticket_timebank.sql
-- Ring time bank ticket: once per turn a member may spend one "time_bank" ticket for +30 seconds,
-- on top of the free +20 seconds per hand. The write fence and meta learn about the extra 30 seconds.
alter table poker_private.ring_hands add column if not exists ticket_revision bigint;
alter table poker_private.ring_hands add column if not exists ticket_used jsonb not null default '{}'::jsonb;

create or replace function poker_private.ring_ticket_timebank(p_member uuid,p_reservation uuid,p_hand uuid,p_revision bigint,p_request uuid) returns void language plpgsql security definer set search_path='' as $$
declare h poker_private.ring_hands%rowtype;changed timestamptz;prior jsonb;extra interval;
begin
 select * into h from poker_private.ring_hands where id=p_hand;
 if not found or p_request is null or p_revision is null or p_revision<0 or not poker_private.ring_member_eligible(p_member) then raise exception 'Hand unavailable';end if;
 perform 1 from public.poker_ring_tables where id=h.table_id for update;
 select * into h from poker_private.ring_hands where id=p_hand for update;
 if not exists(select 1 from jsonb_array_elements(h.participants) p where (p->>'memberId')::uuid=p_member and (p->>'reservationId')::uuid=p_reservation) then raise exception 'Not in hand';end if;
 prior:=h.ticket_used->(p_reservation::text||':'||p_revision::text);
 if prior is not null then
  if prior->>'request'=p_request::text then return;end if;
  raise exception 'Ticket already used';
 end if;
 if h.status<>'active' or h.version<>p_revision+1 or h.ticket_revision=h.version then raise exception 'Turn changed';end if;
 if not exists(select 1 from poker_private.ring_fund_reservations where id=p_reservation and member_id=p_member and table_id=h.table_id and status='seated' and sit_out_since is null) then raise exception 'Seat unavailable';end if;
 select created_at into changed from poker_private.ring_hand_commits where hand_id=h.id and version=h.version;
 extra:=case when h.bank_revision=h.version then interval '20 seconds' else interval '0 seconds' end;
 if changed is null or clock_timestamp()>=changed+interval '20 seconds'+extra then raise exception 'Turn expired';end if;
 if not poker_private.ticket_use(p_member,'time_bank','bank:'||p_hand::text||':'||p_revision::text) then raise exception 'No ticket';end if;
 update poker_private.ring_hands set ticket_used=ticket_used||jsonb_build_object(p_reservation::text||':'||p_revision::text,jsonb_build_object('request',p_request)),ticket_revision=h.version where id=h.id;
end;$$;
revoke all on function poker_private.ring_ticket_timebank(uuid,uuid,uuid,bigint,uuid) from public,anon,authenticated;
grant execute on function poker_private.ring_ticket_timebank(uuid,uuid,uuid,bigint,uuid) to service_role;
create or replace function public.poker_ring_ticket_timebank(p_member uuid,p_reservation uuid,p_hand uuid,p_revision bigint,p_request uuid) returns void language sql set search_path='' as $$select poker_private.ring_ticket_timebank(p_member,p_reservation,p_hand,p_revision,p_request);$$;
revoke all on function public.poker_ring_ticket_timebank(uuid,uuid,uuid,bigint,uuid) from public,anon,authenticated;
grant execute on function public.poker_ring_ticket_timebank(uuid,uuid,uuid,bigint,uuid) to service_role;

create or replace function poker_private.ring_play_write_v2(p_hand uuid,p_expected bigint,p_write uuid,p_sealed jsonb,p_result jsonb,p_timeout boolean,p_from integer,p_actor uuid) returns bigint language plpgsql security definer set search_path='' as $$
declare tid uuid;changed timestamptz;v bigint;extra interval;actor poker_private.ring_fund_reservations%rowtype;
begin
 select table_id into tid from poker_private.ring_hands where id=p_hand;
 perform 1 from public.poker_ring_tables where id=tid for update;
 if not exists(select 1 from poker_private.ring_hand_commits where hand_id=p_hand and request_id=p_write) then
  select * into actor from poker_private.ring_fund_reservations where id=p_actor and table_id=tid and status='seated' for update;
  if not found or not exists(select 1 from poker_private.ring_hands h,jsonb_array_elements(h.participants) p where h.id=p_hand and (p->>'reservationId')::uuid=p_actor) then raise exception 'Actor unavailable';end if;
  if not p_timeout and actor.sit_out_since is not null then raise exception 'Player sitting out';end if;
  -- Free bank +20s and ticket bank +30s for the turn being written.
  select (case when bank_revision=p_expected then interval '20 seconds' else interval '0 seconds' end)+(case when ticket_revision=p_expected then interval '30 seconds' else interval '0 seconds' end) into extra from poker_private.ring_hands where id=p_hand;
  select created_at into changed from poker_private.ring_hand_commits where hand_id=p_hand and version=p_expected;
  if changed is null or p_timeout is null or (p_timeout and actor.sit_out_since is null and clock_timestamp()<changed+interval '20 seconds'+extra) or (not p_timeout and clock_timestamp()>=changed+interval '20 seconds'+extra) then raise exception 'Turn deadline changed';end if;
  if p_from is null or p_from not in(0,3,4,5) then raise exception 'Invalid board phase';end if;
  v:=poker_private.ring_hand_write(p_hand,p_expected,p_write,p_sealed,p_result);
  update poker_private.ring_fund_reservations set timeout_streak=case when p_timeout then least(3,timeout_streak+1) else 0 end,sit_out_since=case when p_timeout and timeout_streak>=2 then coalesce(sit_out_since,clock_timestamp()) else sit_out_since end where id=p_actor and status='seated';
  if p_result is not null then update poker_private.ring_fund_reservations set sit_out_hands=sit_out_hands+1 where table_id=tid and status='seated' and sit_out_since is not null;end if;
  if p_result is not null then update poker_private.ring_hands set runout_from=p_from where id=p_hand;end if;
 else v:=poker_private.ring_hand_write(p_hand,p_expected,p_write,p_sealed,p_result);
 end if;
 return v;
end;$$;

create or replace function poker_private.ring_play_meta(p_table uuid) returns jsonb language sql security definer set search_path='' as $$
 select jsonb_build_object('context',poker_private.ring_context(p_table),'now',clock_timestamp(),'changedAt',(select c.created_at from poker_private.ring_hand_commits c where c.hand_id=h.id and c.version=h.version),'lastHandId',h.id,'completedAt',h.completed_at,'runoutFrom',h.runout_from,'bankRevision',case when h.bank_revision=h.version then h.bank_revision else null end,'bankUsed',coalesce((select jsonb_object_agg(key,value->>'request') from jsonb_each(h.bank_used)),'{}'::jsonb),
 'ticketRevision',case when h.ticket_revision=h.version then h.ticket_revision else null end,
 'penalties',coalesce((select jsonb_object_agg(r.id::text,jsonb_build_object('strikes',r.timeout_streak,'since',r.sit_out_since,'hands',r.sit_out_hands)) from poker_private.ring_fund_reservations r where r.table_id=p_table and r.status='seated'),'{}'::jsonb),'ready',coalesce((select jsonb_agg(r.id) from poker_private.ring_fund_reservations r where r.table_id=p_table and r.status='seated' and r.play_enabled  and r.exit_request is null),'[]'::jsonb))
 from (select 1) stub left join lateral(select * from poker_private.ring_hands where table_id=p_table order by created_at desc,id desc limit 1) h on true;
$$;

-- 20261027030000_poker_structure_time_bank_cards.sql
-- Tournament settings: turn time (20 or 30 seconds), time bank cards at start (1-5) and optional
-- final table cards (0-5). The keys are optional so saved tournaments stay valid (defaults 20s / 2 cards / none).
create or replace function public.valid_poker_structure(s jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare p jsonb; levels integer:=0; previous_sb bigint:=0; previous_bb bigint:=0; sb bigint; bb bigint; ante bigint; mins integer;
begin
 if s is null or jsonb_typeof(s) is distinct from 'object' or not(s ?& array['startingStack','anteType','lateRegLevel','reentry','periods']) or jsonb_typeof(s->'startingStack')<>'number' or (s->>'startingStack')!~'^[0-9]+$' or (s->>'startingStack')::bigint not between 1 and 1000000000
 or coalesce(s->>'anteType','') not in ('none','bb','per-player') or jsonb_typeof(s->'reentry')<>'boolean' or jsonb_typeof(s->'periods')<>'array' then return false; end if;
 if s ? 'turnSeconds' and (s->'turnSeconds') not in ('20'::jsonb,'30'::jsonb) then return false; end if;
 if s ? 'timeBankCards' and (jsonb_typeof(s->'timeBankCards')<>'number' or (s->>'timeBankCards')!~'^[1-5]$') then return false; end if;
 if s ? 'finalTableCards' and (jsonb_typeof(s->'finalTableCards')<>'number' or (s->>'finalTableCards')!~'^[0-5]$') then return false; end if;
 if jsonb_array_length(s->'periods') not between 1 and 100 or s->'periods'->0->>'kind' is distinct from 'level' or s->'periods'->(-1)->>'kind' is distinct from 'level' then return false; end if;
 for p in select value from jsonb_array_elements(s->'periods') loop
  if jsonb_typeof(p) is distinct from 'object' or not(p ?& array['kind','minutes','sb','bb','ante','note']) or coalesce(p->>'kind','') not in ('level','break') or jsonb_typeof(p->'minutes')<>'number' or (p->>'minutes')!~'^[0-9]+$' or jsonb_typeof(p->'note')<>'string' or length(p->>'note')>200 then return false; end if;
  mins:=(p->>'minutes')::integer;if mins not between 1 and 240 then return false; end if;
  if p->>'kind'='level' then
   if jsonb_typeof(p->'sb')<>'number' or jsonb_typeof(p->'bb')<>'number' or jsonb_typeof(p->'ante')<>'number' or (p->>'sb')!~'^[0-9]+$' or (p->>'bb')!~'^[0-9]+$' or (p->>'ante')!~'^[0-9]+$' then return false; end if;
   sb:=(p->>'sb')::bigint;bb:=(p->>'bb')::bigint;ante:=(p->>'ante')::bigint;
   if sb not between 1 and 1000000000 or bb<sb or bb>1000000000 or ante not between 0 and 1000000000 or sb<previous_sb or bb<previous_bb or (s->>'anteType'='none' and ante<>0) then return false; end if;
   previous_sb:=sb;previous_bb:=bb;levels:=levels+1;
  else
   if p->'sb'<>'0'::jsonb or p->'bb'<>'0'::jsonb or p->'ante'<>'0'::jsonb then return false; end if;
  end if;
 end loop;
 if jsonb_typeof(s->'lateRegLevel')<>'number' or (s->>'lateRegLevel')!~'^[0-9]+$' then return false; end if;
 return (s->>'lateRegLevel')::integer between 0 and levels;
exception when others then return false;
end;
$$;

-- 20261027040000_poker_ring_timebank_at_deadline.sql
-- The free ring time bank is now spent automatically by the runner when the 20s turn runs out (owner 2026/10/27).
-- So it is accepted at/after 20s as long as the turn has not moved on (same version = no timeout written yet), up to the extended 40s deadline.
create or replace function poker_private.ring_timebank(p_member uuid,p_reservation uuid,p_hand uuid,p_revision bigint,p_request uuid) returns void language plpgsql security definer set search_path='' as $$
declare h poker_private.ring_hands%rowtype;changed timestamptz;prior jsonb;
begin
 select * into h from poker_private.ring_hands where id=p_hand;
 if not found or p_request is null or p_revision is null or p_revision<0 or not poker_private.ring_member_eligible(p_member) then raise exception 'Hand unavailable';end if;
 perform 1 from public.poker_ring_tables where id=h.table_id for update;
 select * into h from poker_private.ring_hands where id=p_hand for update;
 if not exists(select 1 from jsonb_array_elements(h.participants) p where (p->>'memberId')::uuid=p_member and (p->>'reservationId')::uuid=p_reservation) then raise exception 'Not in hand';end if;
 prior:=h.bank_used->p_reservation::text;
 if prior is not null then
  if prior->>'request'=p_request::text and (prior->>'revision')::bigint=p_revision then return;end if;
  raise exception 'Timebank already used';
 end if;
 if h.status<>'active' or h.version<>p_revision+1 then raise exception 'Turn changed';end if;
 if not exists(select 1 from poker_private.ring_fund_reservations where id=p_reservation and member_id=p_member and table_id=h.table_id and status='seated') then raise exception 'Seat unavailable';end if;
 select created_at into changed from poker_private.ring_hand_commits where hand_id=h.id and version=h.version;
 if changed is null or clock_timestamp()>=changed+interval '40 seconds' then raise exception 'Turn expired';end if;
 update poker_private.ring_hands set bank_used=bank_used||jsonb_build_object(p_reservation::text,jsonb_build_object('request',p_request,'revision',p_revision)),bank_revision=h.version where id=h.id;
end;$$;

-- 20261027080000_poker_ring_refill.sql
-- Free refill (owner 2026/10/27: "チップはなくなったら補充"). Ring chips are free and can never be bought or cashed out.
-- A member with nothing at a table and fewer chips than the table's minimum buy-in (p_table; without it the smallest
-- open table's) tops back up to 3,000. Used by 「補充して座り直す」 at the table right after busting.
-- The ledger's kind checks are widened with a new 'refill' kind (old rows keep matching).
alter table poker_private.ring_chip_ledger drop constraint if exists ring_chip_ledger_kind_check; do $release$ begin alter table poker_private.ring_chip_ledger add constraint ring_chip_ledger_kind_check check(kind in('welcome','reserve','refund','settlement','cashout','refill')); exception when duplicate_object or duplicate_table or duplicate_function or undefined_function then null; end $release$;;
alter table poker_private.ring_chip_ledger drop constraint if exists ring_chip_ledger_check; do $release$ begin alter table poker_private.ring_chip_ledger add constraint ring_chip_ledger_check check(
 (kind='welcome' and available_delta=3000 and in_play_delta=0 and reservation_id is null and hand_id is null) or
 (kind='reserve' and available_delta<0 and in_play_delta=-available_delta and reservation_id is not null and hand_id is null) or
 (kind='refund' and available_delta>0 and in_play_delta=-available_delta and reservation_id is not null and hand_id is null) or
 (kind='cashout' and available_delta>=0 and in_play_delta=-available_delta and reservation_id is not null and hand_id is null) or
 (kind='settlement' and available_delta=0 and reservation_id is not null and hand_id is not null) or
 (kind='refill' and available_delta>0 and available_delta<=3000 and in_play_delta=0 and reservation_id is null and hand_id is null)); exception when duplicate_object or duplicate_table or duplicate_function or undefined_function then null; end $release$;;

create or replace function public.poker_ring_refill(p_request uuid,p_table uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare who uuid:=auth.uid();a poker_private.ring_accounts%rowtype;smallest bigint;
begin
 if who is null or p_request is null or coalesce(public.is_suspended(),true) or not poker_private.ring_member_eligible(who) then raise exception 'Login required';end if;
 perform poker_private.ensure_ring_welcome(who);
 select * into a from poker_private.ring_accounts where member_id=who for update;
 if not found then raise exception 'Account unavailable';end if;
 -- A retried request returns the same balance without topping up twice.
 if exists(select 1 from poker_private.ring_chip_ledger where member_id=who and request_id=p_request) then return poker_private.ring_balance();end if;
 select coalesce(min(min_buy_in),1) into smallest from public.poker_ring_tables where published and deleted_at is null and (p_table is null or id=p_table);
 if p_table is not null and not exists(select 1 from public.poker_ring_tables where id=p_table and published and deleted_at is null) then raise exception 'Table unavailable';end if;
 if a.in_play>0 or a.available>=least(smallest,3000) then raise exception 'Refill not needed';end if;
 update poker_private.ring_accounts set available=3000,updated_at=now() where member_id=who;
 insert into poker_private.ring_chip_ledger(member_id,request_id,kind,available_delta,in_play_delta) values(who,p_request,'refill',3000-a.available,0);
 return poker_private.ring_balance();
end;$$;
revoke all on function public.poker_ring_refill(uuid,uuid) from public,anon,service_role;
grant execute on function public.poker_ring_refill(uuid,uuid) to authenticated;

-- 20261027090000_poker_ring_player_hud.sql
-- Player HUD at ring tables (2026/10/27).
-- 1) poker_display.ring_member_profiles existed only on staging; it is recorded here so production gets it too.
--    It now also returns the viewer's own colour label for each seat and marks the viewer's seat.
-- 2) poker_ring_member_hud: tendency stats (ring hands only) for the member in one seat, plus the viewer's private note.
-- 3) poker_ring_member_note_set: private note / colour label, visible only to the member who wrote it.
-- Member ids never leave the database: callers address players by table + seat.
create schema if not exists poker_display;
revoke all on schema poker_display from public,anon;
grant usage on schema poker_display to authenticated;

create table if not exists poker_private.member_notes(
 owner_id uuid not null,
 target_id uuid not null,
 note text not null default '' check(length(note)<=500),
 color text check(color is null or color in('red','orange','yellow','green','blue','purple')),
 updated_at timestamptz not null default now(),
 primary key(owner_id,target_id),
 check(owner_id<>target_id)
);
alter table poker_private.member_notes enable row level security;
revoke all on poker_private.member_notes from public,anon,authenticated;

create or replace function poker_display.ring_member_profiles(p_table uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare who uuid:=auth.uid();
begin
 if who is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or public.is_suspended() is distinct from false then raise exception 'Not authorized'; end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('seat',r.seat_number,'displayName',left(coalesce(nullif(p.display_name,''),'会員'),80),'avatarUrl',p.avatar_url,
    'you',r.member_id=who,'color',n.color) order by r.seat_number),'[]'::jsonb)
  from poker_private.ring_fund_reservations r join public.poker_ring_tables t on t.id=r.table_id and t.published and t.deleted_at is null
  left join public.profiles p on p.user_id=r.member_id
  left join poker_private.member_notes n on n.owner_id=who and n.target_id=r.member_id
  where r.table_id=p_table and r.status='seated');
end; $$;
revoke all on function poker_display.ring_member_profiles(uuid) from public,anon;
grant execute on function poker_display.ring_member_profiles(uuid) to authenticated;

create or replace function public.poker_ring_member_profiles(p_table uuid)
returns jsonb language sql stable set search_path='' as $$select poker_display.ring_member_profiles(p_table);$$;
revoke all on function public.poker_ring_member_profiles(uuid) from public,anon;
grant execute on function public.poker_ring_member_profiles(uuid) to authenticated;

-- Seated member at a live published table, or null.
create or replace function poker_display.ring_seat_member(p_table uuid,p_seat integer)
returns uuid language sql stable security definer set search_path='' as $$
 select r.member_id from poker_private.ring_fund_reservations r join public.poker_ring_tables t on t.id=r.table_id and t.published and t.deleted_at is null
 where r.table_id=p_table and r.seat_number=p_seat and r.status='seated' limit 1;
$$;
revoke all on function poker_display.ring_seat_member(uuid,integer) from public,anon,authenticated;

create or replace function poker_display.ring_member_hud(p_table uuid,p_seat integer)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare who uuid:=auth.uid();target uuid;s jsonb;n record;
begin
 if who is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or public.is_suspended() is distinct from false then raise exception 'Not authorized'; end if;
 if p_seat is null or p_seat not between 1 and 6 then raise exception 'Invalid seat'; end if;
 target:=poker_display.ring_seat_member(p_table,p_seat);
 if target is null then return null; end if;
 s:=poker_private.hand_stats_summary(target,'ring');
 select note,color into n from poker_private.member_notes where owner_id=who and target_id=target;
 return jsonb_build_object('seat',p_seat,'you',target=who,
  'stats',jsonb_build_object('hands',s->'hands','vpip',s->'vpip','pfr',s->'pfr','threeBet',s->'three_bet','threeBetOpp',s->'three_bet_opp',
   'cbet',s->'cbet','cbetOpp',s->'cbet_opp','foldTo3Bet',s->'fold_to_3bet','foldTo3BetOpp',s->'fold_to_3bet_opp',
   'foldToCbet',s->'fold_to_cbet','foldToCbetOpp',s->'fold_to_cbet_opp','sawFlop',s->'saw_flop','wtsd',s->'wtsd','wsd',s->'wsd'),
  'note',case when target=who then null else coalesce(n.note,'') end,'color',case when target=who then null else n.color end);
end; $$;
revoke all on function poker_display.ring_member_hud(uuid,integer) from public,anon;
grant execute on function poker_display.ring_member_hud(uuid,integer) to authenticated;

create or replace function public.poker_ring_member_hud(p_table uuid,p_seat integer)
returns jsonb language sql stable set search_path='' as $$select poker_display.ring_member_hud(p_table,p_seat);$$;
revoke all on function public.poker_ring_member_hud(uuid,integer) from public,anon;
grant execute on function public.poker_ring_member_hud(uuid,integer) to authenticated;

create or replace function poker_display.ring_member_note_set(p_table uuid,p_seat integer,p_note text,p_color text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare who uuid:=auth.uid();target uuid;clean text:=left(btrim(coalesce(p_note,'')),500);
begin
 if who is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) or public.is_suspended() is distinct from false then raise exception 'Not authorized'; end if;
 if p_seat is null or p_seat not between 1 and 6 then raise exception 'Invalid seat'; end if;
 if p_color is not null and p_color not in('red','orange','yellow','green','blue','purple') then raise exception 'Invalid color'; end if;
 target:=poker_display.ring_seat_member(p_table,p_seat);
 if target is null then raise exception 'Seat is empty'; end if;
 if target=who then raise exception 'Cannot note yourself'; end if;
 if clean='' and p_color is null then
  delete from poker_private.member_notes where owner_id=who and target_id=target;
 else
  insert into poker_private.member_notes(owner_id,target_id,note,color,updated_at) values(who,target,clean,p_color,now())
  on conflict(owner_id,target_id) do update set note=excluded.note,color=excluded.color,updated_at=now();
 end if;
 return jsonb_build_object('seat',p_seat,'note',clean,'color',p_color);
end; $$;
revoke all on function poker_display.ring_member_note_set(uuid,integer,text,text) from public,anon;
grant execute on function poker_display.ring_member_note_set(uuid,integer,text,text) to authenticated;

create or replace function public.poker_ring_member_note_set(p_table uuid,p_seat integer,p_note text,p_color text)
returns jsonb language sql set search_path='' as $$select poker_display.ring_member_note_set(p_table,p_seat,p_note,p_color);$$;
revoke all on function public.poker_ring_member_note_set(uuid,integer,text,text) from public,anon;
grant execute on function public.poker_ring_member_note_set(uuid,integer,text,text) to authenticated;

commit;
